#!/usr/bin/env python3
"""OFFLINE LAB ONLY: explicit Pillow/libjpeg encoder and FFmpeg luma oracle.

Run with an explicit --lab-authority label. Neither tool is a production dependency.
Pillow 12.3.0's linked libjpeg produces paired baseline/progressive quantized images.
Foreign pixels are never generated by the Rust implementation under test.
"""
import argparse
import hashlib
import io
import json
from pathlib import Path
import subprocess

from PIL import Image, features


def scans(data):
    """Independently record scan selectors and spectral/successive-approximation fields."""
    result = []
    pos = 2
    while pos < len(data):
        assert data[pos] == 255
        while data[pos] == 255:
            pos += 1
        marker = data[pos]
        pos += 1
        if marker == 217:
            return result
        size = int.from_bytes(data[pos:pos+2], 'big')
        payload = data[pos+2:pos+size]
        pos += size
        if marker != 218:
            continue
        n = payload[0]
        result.append({'components': [payload[1+i*2] for i in range(n)],
                       'ss': payload[1+n*2], 'se': payload[2+n*2],
                       'ah': payload[3+n*2] >> 4, 'al': payload[3+n*2] & 15})
        while pos < len(data):
            if data[pos] != 255:
                pos += 1
            elif data[pos+1] == 0 or 208 <= data[pos+1] <= 215:
                pos += 2
            else:
                break
    raise ValueError('missing EOI')


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--lab-authority', required=True)
    parser.add_argument('--output', type=Path, default=Path(__file__).parent)
    args = parser.parse_args()
    if not args.lab_authority.strip():
        parser.error('nonempty lab authority required')
    if Image.__version__ != '12.3.0':
        raise RuntimeError('reproduction requires Pillow 12.3.0')
    args.output.mkdir(parents=True, exist_ok=True)
    cases = []
    for mode, sampling, suffix in [('L', 0, 'gray'), ('RGB', 0, '444'), ('RGB', 1, '422'), ('RGB', 2, '420')]:
        for restart in [0, 2]:
            w, h = (37, 29) if restart else (17, 19)
            pixels = bytearray()
            for y in range(h):
                for x in range(w):
                    channels = [(x*17+y*11+(x*y)%41)%256,
                                (x*3+y*29+(x^y)*7)%256,
                                (x*31+y*5+(x*y)%67)%256]
                    pixels.extend(channels[:1] if mode == 'L' else channels)
            image = Image.frombytes(mode, (w, h), bytes(pixels))
            name = f'{suffix}_{w}x{h}_rst{restart}'
            artifacts = {}
            for progressive in [False, True]:
                buffer = io.BytesIO()
                image.save(buffer, format='JPEG', quality=73, optimize=True, progressive=progressive,
                           subsampling=sampling, restart_marker_blocks=restart,
                           comment=b'FSS offline progressive JPEG fixture')
                data = buffer.getvalue()
                filename = name + ('.progressive.jpg' if progressive else '.baseline.jpg')
                (args.output/filename).write_bytes(data)
                artifacts['progressive' if progressive else 'baseline'] = {
                    'file': filename, 'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}
                if progressive:
                    scan_fields = scans(data)
                    restart_count = sum(data.count(bytes([255, i])) for i in range(208, 216))
                    assert len(scan_fields) >= 6
                    assert any(s['ah'] > 0 and s['ss'] > 0 for s in scan_fields)
                    assert bool(restart_count) == bool(restart)
            source = args.output/artifacts['progressive']['file']
            pixel_format = 'gray' if mode == 'L' else 'yuvj444p'
            output = subprocess.run(['ffmpeg', '-v', 'error', '-threads', '1', '-i', str(source),
                                     '-f', 'rawvideo', '-pix_fmt', pixel_format, '-threads', '1', 'pipe:1'],
                                    check=True, capture_output=True).stdout
            assert len(output) == w*h*(1 if mode == 'L' else 3)
            luma = output[:w*h]
            luma_file = name + '.ffmpeg.luma'
            (args.output/luma_file).write_bytes(luma)
            cases.append({'name': name, 'width': w, 'height': h, 'interpretation': 'gray' if mode == 'L' else 'ycbcr',
                          'restart_interval': restart, 'restart_markers': restart_count, 'scans': scan_fields,
                          **artifacts, 'luma': {'file': luma_file, 'sha256': hashlib.sha256(luma).hexdigest()}})
    version = subprocess.run(['ffmpeg', '-version'], check=True, capture_output=True, text=True).stdout.splitlines()[0]
    manifest = {'format': 'fss.progressive_jpeg_lab_fixture.v1', 'pillow': Image.__version__,
                'libjpeg': features.version_codec('jpg'), 'ffmpeg': version, 'cases': cases}
    (args.output/'manifest.json').write_text(json.dumps(manifest, indent=2)+'\n')
    print(json.dumps({'cases': len(cases), 'output': str(args.output), 'ffmpeg': version}))


if __name__ == '__main__':
    main()
